window.ScripturaJastrowAppend([{"sid":"R00522","lemma":"צְלָלָא","gloss":"Uma pele pequena, V.צַלָּא.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Uma pele pequena, V.צַלָּא.</p>","gloss_language":"pt-BR"},{"sid":"R00523","lemma":"צַלָּלָא","gloss":"Tanner, V.צַלָּא.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Tanner, V.צַלָּא.</p>","gloss_language":"pt-BR"},{"sid":"R00524","lemma":"צְלֶלְפּוֹנִי","gloss":"Ver הַצְּלֶלְפּוֹנִי.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צְלֶלְפּוֹנִית</p><p><strong>Notas e referências:</strong> , v. הַצְּלֶלְפּוֹנִי</p>","gloss_language":"pt-BR"},{"sid":"R00525","lemma":"צְלַם","gloss":", Pa.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , Pa.</p><p><strong>Notas e referências:</strong> צַלֵּם(denom. deצַלְמָא) para pintar (escuro). B. Mets. 60 B.שרא לצַלּוּמֵי גיריpermitido pintar flechas;לצ&#x27; דיקוליpintar cestas (para melhorar sua aparência).</p>","gloss_language":"pt-BR"},{"sid":"R00526","lemma":"צֶלֶם","gloss":", p. 141 nota) sombra, imagem, imagem.; , v. לוֹכְסָן; a. fr. — Pl.צְלָמִים, צְלָמִין.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> Denom. deצֵל* V. Del Proleg.</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> , p. 141 nota) sombra, imagem, imagem.</p><p><strong>Notas e referências:</strong> Gen. R. s. 8העליונים נבראו בצ&#x27; ובדמות וכOs celestiais são criados na imagem e semelhança (divina);הריני בורא אותו בצ&#x27; ובדמות וכVou criá-lo (o homem) em uma imagem e semelhança para que ele possa participar da natureza dos celestiais &amp;c. Ib. (ref. para Gen. I, 26; 28)את שהוא בצַלְמֵינוּ כדמותינו ורדו וכ&quot;Aquele que está à nossa imagem e semelhança (que imita o Criador) é dito, ur&#x27;du (regra); daquele que não é &amp;c., é dito que você (eles devem descer); Yalk. ib. 14. Ab. III, 14שנברא בצQue ele foi criado à imagem (de Deus). Tanë. Mishp. 19.תנו כבוד לצַלְמוֹ וכDê honra à imagem do Senhor! Gen. R. s. 89חלמא … חלום הצ&#x27; וחלום האילןo sonho e sua interpretação, o sonho da sombra (imaginação) e o sonho da árvore (realidade). Midr. Até, até Ps. XXV, 8על כל … צ&#x27; והיתה וכCada milha era uma estação, e em cada estação era uma figura com uma mão curvada que apontava para os lugares de refúgio &amp;c.; a. fr.-sp. ídolo.צלמו של מיכה; Esth. R. a III, 7, v.מִיכָהEu. Taan. IV, 6 (26 b)והועמד צ&#x27; בהיכלSrta.והעמיד) e um ídolo foi colocado no templo. Ruth R. para II, 14אדם שהעמיד צ&#x27; וכReceberás em arrependimento o homem (Manassé) que pôs um ídolo no Templo? Lam. R. para I, 9צ&#x27; חלולUm ídolo oco. Ib. intrometida. (R. Josh.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> , v. לוֹכְסָן; a. fr. — Pl.צְלָמִים, צְלָמִין.</p><p><strong>Notas e referências:</strong> Meg. 15 b.כיון שהגיעה לבית הצ&#x27; וכQuando ela (Ester) chegou ao quarto dos ídolos (no palácio), a Divina Presença a deixou; e.צַלְמוֹן.]</p>","gloss_language":"pt-BR"},{"sid":"R00527","lemma":"צֶלֶם","gloss":"Targ. General I, 26, Targ XX, 4.בגין דאמר לי צ' פלן וכDesde que certo ídolo me disse &c. Ruth R. para II, 14והוה צווח צ' פלן צ' פלן וכ' e ele (Manassé) gritou, Ó ídolo -, Ó ídolo -, salve-me. Y. Shek. II, fim, 47 A, A.E., V.אֲדוּרֵי; a. fr. - B. Kam. 98 bלצ' (Ms. H.לצִלְמַיָּיה), v. כָּשׁוֹרָא.-- [Y. Kil. VII, implore. 30 dבהדין צ', leia:צוֹנָמָא- Pl.צְלָמַיָּא, צִלְמַ', צִלְמִין, צִלְמֵי, צִיTarg. Y. Lev. XXVI, 1. Is. XLIV, 9 anos, A.F.-Y. Zar. IV, 43 d bot.תבר כל אילין צ' וכQuebre todos aqueles ídolos na casa de banho. Y. Ber. II, 4 b, v.אֲדוּרֵי- B. Kam. 23 b.דשף צלמיQuando o animal esfregou pinturas da parede. Ib. 86 b, v.כָּשׁוֹרָא; a. fr.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צְלַם, צֵלַם, צַלְמָא, צִלְ&#x27;, צִילְ&#x27;</p><p><strong>Informações do original:</strong> mesmo significado.</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Notas e referências:</strong> Targ. General I, 26, Targ XX, 4.בגין דאמר לי צ&#x27; פלן וכDesde que certo ídolo me disse &amp;c. Ruth R. para II, 14והוה צווח צ&#x27; פלן צ&#x27; פלן וכ&#x27; e ele (Manassé) gritou, Ó ídolo -, Ó ídolo -, salve-me. Y. Shek. II, fim, 47 A, A.E., V.אֲדוּרֵי; a. fr. - B. Kam. 98 bלצ&#x27; (Ms. H.לצִלְמַיָּיה), v. כָּשׁוֹרָא.-- [Y. Kil. VII, implore. 30 dבהדין צ&#x27;, leia:צוֹנָמָא- Pl.צְלָמַיָּא, צִלְמַ&#x27;, צִלְמִין, צִלְמֵי, צִיTarg. Y. Lev. XXVI, 1. Is. XLIV, 9 anos, A.F.-Y. Zar. IV, 43 d bot.תבר כל אילין צ&#x27; וכQuebre todos aqueles ídolos na casa de banho. Y. Ber. II, 4 b, v.אֲדוּרֵי- B. Kam. 23 b.דשף צלמיQuando o animal esfregou pinturas da parede. Ib. 86 b, v.כָּשׁוֹרָא; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"R00528","lemma":"צַלְמוֹן","gloss":"(b. h.) pr. n. Zalmon, nome de uma colina perto de Shechem, e de um lugar (v. Neub., Géogr. p. 275).","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) pr. n. Zalmon, nome de uma colina perto de Shechem, e de um lugar (v. Neub., Géogr. p. 275).</p><p><strong>Notas e referências:</strong> Tosef. Par. IX (VIII), 2, V.יוֹרֶדֶת.-Yeb. XVI, 6.צְלָמִין, צְלָמִים; V. Rabb. D. S. A. l. Nota 9). Ber. 15 b, v.צַלְמָוֶת; a. e.</p>","gloss_language":"pt-BR"},{"sid":"R00529","lemma":"צַלְמוֹנָא","gloss":"P.N.P.Zalmonah.; Escuridão, nome de Geena, V.צַלְמָוֶת.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צַלְמוֹנָה</p><p><strong>Informações do original:</strong> צַלְמֹנָה)</p><p><strong>Informações do original:</strong> (b. h.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> P.N.P.Zalmonah.</p><p><strong>Notas e referências:</strong> Y. Orl. I, 61 por top; Y. Maasr. 48 c</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Escuridão, nome de Geena, V.צַלְמָוֶת.</p>","gloss_language":"pt-BR"},{"sid":"R00530","lemma":"צַלְמוֹנִית","gloss":"(denom. deצֶלֶםQuerida imagem, Trnsf. Filho único (cmp.סִבְרוֹנָא).","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (denom. deצֶלֶםQuerida imagem, Trnsf. Filho único (cmp.סִבְרוֹנָא).</p><p><strong>Notas e referências:</strong> Gen. R. s. 94; Midr. Sam. XXX; XXXIIדן נכנס בצַלְמוֹנִיתוֹ וכDan foi para seu pai (para uma bênção) com seu único filho (Gen. XLVI, 23), e foi abençoado com uma posteridade de &amp;c. (Num. I, 39).</p>","gloss_language":"pt-BR"},{"sid":"R00531","lemma":"צַלְמָוֶת","gloss":"(b. h.) = צַלְמוּת, escuridão; (homilet.צֵל מָוֶת) sombra da morte, Geena.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (b. h.) = צַלְמוּת, escuridão; (homilet.צֵל מָוֶת) sombra da morte, Geena.</p><p><strong>Notas e referências:</strong> Mekh. B’shall., Vayassa, s. 1 (ref. a Jer. II, 6)צֵל ועמו מָוֶתsombra e com ele morte (v.עֶכֶס); Tan. ib. 18; Yalk. Jer. 266, Pesik. Trabalho 906 (ref. a Job X, 22)מהו צ&#x27; צא למות וכO que é tsalmaveth? (O anjo Dumah diz, quando o sábado termina, para aqueles que foram liberados da Geena durante o sábado,) Vá para a morte, para os exercícios de sábado (v.סֵדֶרAcabou. Ber. 15 B (ref. a Ps. LXVIII, 15)א&quot;ת בצלמון אלא בצNão leia b’tsalmon, mas b’tsalmaveth (na Geena). R’eh 13 (ref. a Ps. l. c.)הוא צ&#x27; שלהןA neve é o inferno deles.צַלְמוֹנָא; Pesik.צַלְמוֹנָהXXXI, 21 anosצלמונהYalk. Deut. 892צלמונMidr. Até mais. para Ps. XCIIזימן … אחת של אופל ואחת של צO Senhor preparou para Adão duas pedras, uma de Ofel (escuridão) e uma de Tsalmaveth (ref. a Jó XXVIII, 3);</p>","gloss_language":"pt-BR"},{"sid":"R00532","lemma":"צַלְמָנָא","gloss":"(denom. deצֶלֶם) imagem, estátua, ídolo.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִילְמָ&#x27;</p><p><strong>Definição:</strong> (denom. deצֶלֶם) imagem, estátua, ídolo.</p><p><strong>Notas e referências:</strong> Targ. Jud. XVIII, 17 (ed. Lag.צִילְמָא- Pl.צַלְמָנִין, צַלְמָנַיָּא, צִילְTarg. Hos. XIII, 2 (ed. Lag.צלמין).מַחֲלָצַיָּא.</p>","gloss_language":"pt-BR"},{"sid":"R00533","lemma":"צֵלַע","gloss":"Zela.","type":"pr. n. pl.","detailsHtml":"<p><strong>Informações do original:</strong> צֵלָע)</p><p><strong>Informações do original:</strong> (b. h.</p><p><strong>Definição:</strong> Zela.</p><p><strong>Notas e referências:</strong> Targ. II Sam. XXI, 14. Josh. XVIII, 28צְלַע אֶלֶף.</p>","gloss_language":"pt-BR"},{"sid":"R00534","lemma":"צָלַע","gloss":"[para dobrar, pendurar,] para parar; trnsf. ao pecado.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> compararצְלֵיII, a.טְלַע)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> [para dobrar, pendurar,] para parar; trnsf. ao pecado.</p><p><strong>Notas e referências:</strong> Yalk. Num. 764 (ref. a PS. XXXV, 15 sq)כשאני צוֹלַעַת מעט וכAssim que paro um pouco, eles se reúnem contra mim, Pesik. R. s. 13נכים עושים הדין בצוֹלְעִיםOs paralisados executam julgamento na parada (os ímpios punem os frágeis);שמא נכים וחגרים עושים את הדין במי שצוֹלֵעַOs paralíticos e os aleijados são punidos?</p><p><strong>Notas e referências:</strong> Ib.כשאני מְצַלַּעַת וכQuando eu paro, eles se alegram.</p>","gloss_language":"pt-BR"},{"sid":"R00535","lemma":"צֶלַע","gloss":"Precedido.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Precedido.</p><p><strong>Notas e referências:</strong> Pesik.יושבים … הצ&#x27; לבוא עליEles se sentam e olham para fora, quando eu venho para cair, que eles podem vir contra mim. Midr. Até. até Ps. III (ref. toבצלע, II Sam. XVI, 13)מזכיר לו מעשה הצEle (Shimei) o lembrou (David) da história da queda (crime de David); Yalk. Sam. 151.</p>","gloss_language":"pt-BR"},{"sid":"R00536","lemma":"צֵלָע","gloss":"v. צָלַע); Lado, costela.; כל זמן … כאחד וכיון שנטלה צַלְעָתוֹ וכEnquanto ele era Adão, ele era como um (harmônico em si mesmo), mas quando sua costela foi tirada dele, ele era 'saber' (o conflito entre) 'bem e mal', Yalk. Ib.; Asa de um prédio.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צַלְעָה</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> v. צָלַע)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Lado, costela.</p><p><strong>Notas e referências:</strong> 42 bנעקרה צ&#x27; מעיקרהSe uma costela de um animal for arrancada de seu assento. Gen. R. s. 21 (ref. para Gen. III, 2</p><p><strong>Número da acepção:</strong> 2)</p><p><strong>Definição:</strong> כל זמן … כאחד וכיון שנטלה צַלְעָתוֹ וכEnquanto ele era Adão, ele era como um (harmônico em si mesmo), mas quando sua costela foi tirada dele, ele era &#x27;saber&#x27; (o conflito entre) &#x27;bem e mal&#x27;, Yalk. Ib.</p><p><strong>Notas e referências:</strong> 34.צַלְעָתִי מהוSe alguém diz a uma mulher, &#x27;seja tu minha costela&#x27; (aludindo a Gen. II, 22), como isso é reconhecido como um noivado?צְלָעוֹת. ull. III, 1נשתברו רוב צַלְעוֹתֶיהָSe o maior número de costelas de um animal estiver quebrado. Ib. 52 aובצ&#x27; גדולות וכE isso significa as grandes costelas, aquelas que têm medula em seus ossos, lado de uma colina ou rocha. Como ab. Shebi.צִילְעוֹתConstr., V.פּוּאָה.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> Asa de um prédio.</p><p><strong>Notas e referências:</strong> B. Bath. 61 a</p>","gloss_language":"pt-BR"},{"sid":"R00537","lemma":"צַלָּעָה","gloss":"(צלע; v. צַלָּא) trabalhador ou negociante de couro.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (צלע; v. צַלָּא) trabalhador ou negociante de couro.</p><p><strong>Notas e referências:</strong> - Pl.צַלָּעֵיNed, 56 b.שוקא דצO mercado de couro.</p>","gloss_language":"pt-BR"},{"sid":"R00538","lemma":"צָלַף","gloss":"(cmp.צלל) para vibrar.; para balançar (um chicote); para atacar.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (cmp.צלל) para vibrar.</p><p><strong>Definição:</strong> para balançar (um chicote); para atacar.</p><p><strong>Notas e referências:</strong> Yoma V, 3, sq.לא היה … אלא כמַצְלִיףEle não mirava em um certo ponto acima ou abaixo, mas fazia o movimento de balançar um chicote; ib. 15 a; e., v.מַנְגְּדָנָא a. טִבְרֵר.</p>","gloss_language":"pt-BR"},{"sid":"R00539","lemma":"צְלַף","gloss":"Af.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> ch.,</p><p><strong>Definição:</strong> Af.</p><p><strong>Notas e referências:</strong> אַצְלֵיףMesmo. Targ. Ps. LXXIV, 5. Y. Deu. XXV, 3ארבעין יַצְלִיף וכ&#x27; 40 vezes ele deve balançar o chicote, mas golpear um a menos.</p>","gloss_language":"pt-BR"},{"sid":"R00540","lemma":"צְלָף","gloss":"Arremesso.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Arremesso.</p><p><strong>Notas e referências:</strong> Maasr. IV, 6הצ&#x27; מתעשר וכDa alcaparra os dízimos devem ser dados dos rebentos de palmeiras, do fruto, e da flor (v. Löw, Pfl, p. 264); Ber. 36 a (idêntico comנִצְפָּה). B. Bath. 28 bאכלה … כגון צ&#x27; se uma parte de três produtos da mesma árvore dentro de três dias, como por exemplo, a alcaparra. Sabb. 30b.אחוי ליה צ&#x27; ele apontou por meio de um exemplo para a alcaparra (dos quais os vários produtos são comidos sucessivamente). Ib. 150 b, v.נִצְפָּהApostas. 25 B; A.F. — Pl.צְלָפִים, צְלָפִיןSabb. 110 aמי צAlcaparra.</p>","gloss_language":"pt-BR"},{"sid":"R00541","lemma":"צִלְצוּל","gloss":"(צָלַל; cmp.גִּלְגְּלִין, fr.גָּלַל) cinto de rede de trabalho (para apoiar o peito, considerado indecente); bandagem, envoltório.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִילְ&#x27;</p><p><strong>Definição:</strong> (צָלַל; cmp.גִּלְגְּלִין, fr.גָּלַל) cinto de rede de trabalho (para apoiar o peito, considerado indecente); bandagem, envoltório.</p><p><strong>Notas e referências:</strong> Sabb. 62 b (ref. para Is. III, 24)מקום שהיו חגורות בצ&#x27; וכO lugar no corpo onde eles estavam cingidos com uma cinta fica cheio de hematomas. Sot. 8 b; 9 aהיא חגרה לו בצEla (a adúltera) colocou um cinto fino para o bem dele, portanto o padre traz uma corda Tosef. ib. III, 4בצִיצִיןEd Zuck. (Var.בצצין; oth. ed.בפנים; corr. acc.). Y. Yoma VI, 43 d topהלבישו … וחגרו צִלְצָלEle o fez vestir uma roupa íntima e cingi-lo com uma cinta (como uma mulher);בצילצולZeb. 19 aצ&#x27; קטןum pequeno cinto (usado como um curativo); a. fr.</p>","gloss_language":"pt-BR"},{"sid":"R00542","lemma":"צִלְצוֹלִין","gloss":"Pl. ch. Targ. Y. Num. V, 18. — Gen. R. s. 19צִילְצְלִין; Yalk. ib. 27צִיצְלִין.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִילְ&#x27;</p><p><strong>Notas e referências:</strong> Pl. ch. Targ. Y. Num. V, 18. — Gen. R. s. 19צִילְצְלִין; Yalk. ib. 27צִיצְלִין.</p>","gloss_language":"pt-BR"},{"sid":"R00543","lemma":"צִלְצֵל","gloss":"(v. צָלַל); para vibrar, para ter um anel limpo.; Bater palmas.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (v. צָלַל)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para vibrar, para ter um anel limpo.</p><p><strong>Notas e referências:</strong> Y. Succ. V, bot 55 c.ולא היה מְצַלְצֵל וכE não tinha o anel claro como antes.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Bater palmas.</p><p><strong>Notas e referências:</strong> Pirké d’R. El. ch. XVIIומְצַלְצֶלֶת בכפיהEla bateu palmas com alegria. Reis 232ומסלסלת בכפי ידיה).</p>","gloss_language":"pt-BR"},{"sid":"R00544","lemma":"צַלְצֵל","gloss":"Gritar ou gritar.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> Gritar ou gritar.</p><p><strong>Notas e referências:</strong> Y. Ter. VIII, 46 b bot.שרי מְצַלְצֵלEle começou a gritar.</p>","gloss_language":"pt-BR"},{"sid":"R00545","lemma":"צֶלְצָל","gloss":"Precedido.; címbalo.; Sombra, cobertura.טְלָלָא).","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִילְ&#x27;</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Precedido.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> címbalo.</p><p><strong>Notas e referências:</strong> Y. Succ. V, bot 55 c.צ&#x27; של מקדש וכO címbalo do Templo se originou dos dias de Moisés. Bot 55 b.מיריחו … הציEm Jericó eles podiam ouvir o som do címbalo (do Templo). Shek. V, 1בן ארזא על הצBen Arza tinha o comando do címbalo. Y. ib. bot 48 d.הניף … והקיש בן א&#x27; בצQuando o Sagan acenou a bandeira, B. A. atingiu o címbalo, Tam. VII, 3; Cant. R. para IV, 4. II, 5והצ&#x27; לבדApenas um único címbalo foi usado no Templo.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Sombra, cobertura.טְלָלָא).</p><p><strong>Notas e referências:</strong> B. Bath. 75 a, contra. paraסוכה(Rashb.צֵלYalk. Is. 361 (v. Rabb. D. S. B. Bath. l. c. nota 9).</p>","gloss_language":"pt-BR"},{"sid":"R00546","lemma":"צַלצְלָא","gloss":"Ver צוֹצְלָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צוֹצְלָא</p>","gloss_language":"pt-BR"},{"sid":"R00547","lemma":"צִלְצַלְוָן","gloss":"= h. צֶלְצָל, címbalo.","type":"Substantivo masculino plural","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צֶלְצְלִין, צִילְ&#x27;</p><p><strong>Definição:</strong> = h. צֶלְצָל, címbalo.</p><p><strong>Notas e referências:</strong> Targ. Ps. CL, 5. Eu sou Sam.חליל). Ib. XVIII, 6 (h. textoשלשיםTarg. II Sam. VI, 5; I Chr. XIII, 8.</p>","gloss_language":"pt-BR"},{"sid":"R00548","lemma":"צִלְצַלְתָּא","gloss":"Ver צוֹצְלָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צוֹצְלָא</p>","gloss_language":"pt-BR"},{"sid":"R00549","lemma":"צְלַק","gloss":"(cmp.צלח) para dividir.; para ser dividido.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (cmp.צלח) para dividir.</p><p><strong>Notas e referências:</strong> Ultimo. 124 a.דצַלְקֵיה מִצְלַקQuando ele dividiu o fogão pela largura, V.גִּיסְטְרָא.</p><p><strong>Definição:</strong> para ser dividido.</p><p><strong>Notas e referências:</strong> Ber. 56 bושרו לחבלא עד דא&#x27; רישיה שרו לחבלא אזל כל חד וחד וקם אדוכתיה וא&#x27; (Ms. M.אסתליקDeixe a corda ir até que ele seja dividido em sua cabeça. Eles soltaram a corda, quando cada árvore voltou à sua posição natural, e seu corpo foi despedaçado.</p>","gloss_language":"pt-BR"},{"sid":"R00550","lemma":"צָלֶקֶת","gloss":"(precedido; cmp.חֲזָזִית) uma superfície áspera, escamosa, cicatriz.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (precedido; cmp.חֲזָזִית) uma superfície áspera, escamosa, cicatriz.</p><p><strong>Notas e referências:</strong> Keth. 75 a se um cachorro a mordeu,ונעשה מקומו צE o ponto da mordida ficou marcado. Nidd. 55 aבשר … צSe um pedaço de carne for cortado, o ponto fica marcado. Sifra Thazr. (sinônimo comצָרֶבֶת). V. צוּלְקָא.</p>","gloss_language":"pt-BR"},{"sid":"R00551","lemma":"צַלְתָּא","gloss":"Tsalta.","type":"pr. n. pl.","detailsHtml":"<p><strong>Definição:</strong> Tsalta.</p><p><strong>Notas e referências:</strong> Bekh. 21 bרעותא דצOs pastores de Tsalta.</p>","gloss_language":"pt-BR"},{"sid":"R00552","lemma":"צם","gloss":"Ver צוּם.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צוּם</p>","gloss_language":"pt-BR"},{"sid":"R00553","lemma":"צָמֵא","gloss":"Está com sede.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צְמֵאָה</p><p><strong>Definição:</strong> Está com sede.</p><p><strong>Notas e referências:</strong> Taan. 22 b.לא שכורה ולא צQue o chão não esteja bêbado, nem sedento.צְמֵאִים, צְמֵאִין; צְמֵאוֹתMidr. Até mais. para Ps. CXVIII, 19משקה צ&#x27; הייתיEu costumava dar bebida aos sedentos;והם אומרים לו זה השער לה&#x27; משקה צ&#x27; הכנס בוEd. Bub. e eles (no céu) dizer-lhe, &#x27;esta é a porta do Senhor &#x27;, tu, que tem sido um dador de bebida para os sedentos, entrar assim. Ib. para Ps. XXIIוכשצ&#x27; כל החיות וכE quando estão com sede, todas as feras se juntam ao redor dela.</p>","gloss_language":"pt-BR"},{"sid":"R00554","lemma":"צָמֵא","gloss":"Precedido.) para ter sede.; para causar a morte da sede.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Precedido.) para ter sede.</p><p><strong>Definição:</strong> para causar a morte da sede.</p><p><strong>Notas e referências:</strong> Sifré Deu. 199 (ref. a Deu. XX, 10להלחם עליה … ולא להַצְמִיאָהּ וכ&#x27;para travar guerra contra ele&#x27;, mas não para deixá-lo morrer de fome ou sede, ou fazê-lo morrer de peste; e..</p>","gloss_language":"pt-BR"},{"sid":"R00555","lemma":"צָמָא","gloss":"Precedido.) sede.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Precedido.) sede.</p><p><strong>Notas e referências:</strong> Ex. R. s. 2לא … מפני צ&#x27; וכNão sabia que fugiste por causa da sede.השותה מים לִצְמָאוֹAquele que bebe água para satisfazer sua sede. Pirké d’R. El. XXXמיתת הצMorte da sede; e.</p>","gloss_language":"pt-BR"},{"sid":"R00556","lemma":"צִמְאָה","gloss":"O mesmo. Yoma 77 a (ref. a Jer. II, 25)מנעי … גרונך לידי צ\"Refreia a tua língua do mal, para que a tua garganta não esteja condenada à sede, Yalk. Jer. 266צִמָּאוֹן; a. e.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> O mesmo. Yoma 77 a (ref. a Jer. II, 25)מנעי … גרונך לידי צ&quot;Refreia a tua língua do mal, para que a tua garganta não esteja condenada à sede, Yalk. Jer. 266צִמָּאוֹן; a. e.</p>","gloss_language":"pt-BR"},{"sid":"R00557","lemma":"צִמָּאוֹן","gloss":"Ver preced..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> M. (B.H.) o mesmo, V. Preced.</p>","gloss_language":"pt-BR"},{"sid":"R00558","lemma":"צָמַד","gloss":"(b. h.) para pressionar juntos, para se juntar, casal.; Para ser apegado, preso.; Para a multidão, faça as malas.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) para pressionar juntos, para se juntar, casal.</p><p><strong>Notas e referências:</strong> Gen. R. s. 5צְמָדָן בין שני בדי הארוןRashi (v. comentário. Y’fath Toar a. l.) ele combinou-os (arranjou-os de acordo com as fileiras) entre as duas barras da Arca (ed., a. Yalk. Josh. 14?סמכן* Lev. R. s. 10שמן- Parte, passo.צָמוּד; f. צְמוּדָה#Num.R.S.12אין צב אלא צְמוּדוֹתtsab (Num. VII, 3) significa bem unidos (vigas, por ref. a Is. XLIX, 22בחצן, v. חוּץI; v. Targ. a. l.).</p><p><strong>Definição:</strong> Para ser apegado, preso.</p><p><strong>Notas e referências:</strong> Bal. 18.ונִצְמְדוּ זה לזו וכ&quot;e eles foram unidos uns aos outros, assim está escrito (Num. XXV, 3), e Israel foi unido &amp;c.; ed. Bub. 28ונִצְמָדִים זה וכ&#x27;.</p><p><strong>Definição:</strong> Para a multidão, faça as malas.</p><p><strong>Notas e referências:</strong> - Parte, passo.מְצוּמָּד; pl.מְצוּמָּדִיםCant. R. para IV, 1צמתך, ib.)נראין מצ&#x27; … כהדין סדרא רבה וכ&#x27; eles parecem estar lotados, e ainda são confortáveis, como no grande salão de escola de Sephoris (cmp. Ab. V, 5).</p>","gloss_language":"pt-BR"},{"sid":"R00559","lemma":"צְמַד","gloss":",; Para se juntar, anexar, arnês.; para amarrar (um membro quebrado).; Para estreitar, reter.; Mesmo,; Amarrar, curar, consertar.; para ser amarrado, reparado.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para se juntar, anexar, arnês.</p><p><strong>Notas e referências:</strong> Parte, passo.צָמִיד; f. צְמִידָא; pl.צְמִידִין, a) Apegado, arrebatado. Targ. I Reis XIX, 19... b) Apegado, viciado, no hábito de. Lam. R. para III, 9הוה צמיד עיית קינדלוי וכ&#x27; Ar. (ed.הוה מסדרא וכY. Maas.הוה עביד(V.עוּתCh.). Lev. R.S. 26הות צמידא אמרה נכ&#x27; (algum Ed.צְמִידָהEra viciado em falar mal.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para amarrar (um membro quebrado).</p><p><strong>Notas e referências:</strong> (um membro quebrado). Targ. Ez. XXXIV, 4, 16.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> Para estreitar, reter.</p><p><strong>Notas e referências:</strong> B. Bath. 53 aדצ&#x27; לה מיא(Ed. Pes. a. oth.דצאמת, v. צְמַתEle reteve a água em benefício do campo, Opp.ארוחDeixe a água se espalhar.</p><p><strong>Definição:</strong> Mesmo,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Amarrar, curar, consertar.</p><p><strong>Notas e referências:</strong> Parte, passo.מְצַמַּדAb. Zar. 55 aדאזלי כי מתברי … מְצַמְּדֵיque vão para um templo idólatra quebrado e saem curados, Yalk. Ex. 289מצמידי(corr. acc., ouמִיצַמְּדֵיIthpe.</p><p><strong>Definição:</strong> para ser amarrado, reparado.</p><p><strong>Notas e referências:</strong> Ber. 22 bא&#x27; חצביה דר&quot;נO lançador de R.N. foi consertado (a regra que ele estabeleceu é restaurada novamente), opp.אתבר, v. חַצְבָּא.</p>","gloss_language":"pt-BR"},{"sid":"R00560","lemma":"צֶמֶד","gloss":"Um par de animais que trabalham amarrados ao jugo.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Um par de animais que trabalham amarrados ao jugo.</p><p><strong>Notas e referências:</strong> B. Bath. V, 1מבר … את הצ&#x27; הבקרSe alguém vendeu ‘um jugo’, ele não vendeu os bois (mas apenas o jugo); ib.אמר מכור לי צִמְדְּךָ וכ&#x27; (Bab. ed. 77 bצִימְ&#x27;) Se ele disse, venda-me o seu jugo por duzentos Zuz, é bem conhecido que um jugo não vale duzentos Zuz (por isso ele quis dizer o jugo de bois); v.צִימְדָּא; Tosef. ib. IV, 1.צ&#x27; של פרותum par de vacas com o jugo, Rashi (Tosaf. Um jugo para vacas, composto por duas peças.מצִמְדָּהּVar. em Ar. s. v.צד, v. תַּבְרָא.</p>","gloss_language":"pt-BR"},{"sid":"R00561","lemma":"צִמְדָּא","gloss":"Ver צִימְדָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צִימְדָּא</p>","gloss_language":"pt-BR"},{"sid":"R00562","lemma":"צמדתא","gloss":"Ver צְמִירְתָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צְמִירְתָּא</p>","gloss_language":"pt-BR"},{"sid":"R00563","lemma":"צִמּוּק","gloss":", V. subצִימּ'.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִמּוּקָא</p><p><strong>Notas e referências:</strong> , V. subצִימּ&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"R00564","lemma":"צַמּוּת","gloss":"Ver צוּמּוּת.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צוּמּוּת</p>","gloss_language":"pt-BR"},{"sid":"R00565","lemma":"צָמַח","gloss":"(b. h.) para romper, brilhar; florescer, brotar, crescer.; ser feito para crescer, crescer.; Para crescer.; Mesmo, v. mesmo, v. Pi.; para fazer crescer, produzir.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) para romper, brilhar; florescer, brotar, crescer.</p><p><strong>Notas e referências:</strong> Cant. R. para III, 6היה … ועמוד אש צוֹמֵחַA coluna de nuvem desceu, e a coluna de fogo ficou mais brilhante. 60 bיצאו דשאים … וצָמְחוּAs plantas saíram e ficaram na abertura do solo, até que Adão orou, quando a chuva caiu, e eles saíram. Pesik. R. s. 46צָמְחָה כפרתוseu perdão foi revelado. Y. Shebi. IX, 38 d topoאם צמחו מוצאי וכSe as folhas saírem depois do ano sabático. Ib.אם צימח וכ&#x27; se (o lof no chão) brotou novamente &amp;c. Maasr. I, 3התלתן כדי שתִּצְמַחM. Fenugrec está sujeita a dízimos quando está tão avançada que as sementes podem ser plantadas e crescerão, R. Hash. 12 b, expl.משתצמח לזרעיםQuando cresceu o suficiente para ser plantado (Rashi: quando suas sementes começam a se desenvolver). Neg. X, 3הצומחum cabelo preto que cresce dolorido (Lev. XIII, 37). Tosef. ib. IV, 1שתי שערות צומחותDois cabelos pretos de crescimento recente. Ib.אחת צוֹמַחַת וכUm de crescimento recente, e o outro (do antigo estado) cercado de carne;</p><p><strong>Definição:</strong> ser feito para crescer, crescer.</p><p><strong>Notas e referências:</strong> Midr. Até mais. Para Ps. XXIIנ&#x27; להם גואל וכUm redentor cresceu para eles e os redimiu. Pirké d’R. El. ch. XIIנִצְמָהִין מאליהןcresceram de si mesmos (sem serem plantados); e.</p><p><strong>Definição:</strong> Para crescer.</p><p><strong>Notas e referências:</strong> Y. Shebi. l. c., v. supra. Y. Maasr. I, 49 a top (ref. a Deu. XIV, 22)דבר שהוא נזרע ומְצַמֵּחַ(R.S. para Maasr. I, 3ומצְמִיחִ) que é suficientemente avançado para crescer quando plantado (v. supra); e.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Mesmo, v. mesmo, v. Pi.</p><p><strong>Definição:</strong> para fazer crescer, produzir.</p><p><strong>Notas e referências:</strong> Sifre Deut. 307, V.צִידּוּק.</p>","gloss_language":"pt-BR"},{"sid":"R00566","lemma":"צְמַח","gloss":"Mesmo. Targ. O. Ex. X, 5 (Y. mesmo.; para fazer crescer, produzir.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Notas e referências:</strong> Targ. Gen. II, 5. Targ. Ez. VII, 10.שדי … ולא צEle colocou sementes, mas não brotaram.אתא מיטרא וצ&#x27; uma chuva veio, e brotou. Y. Kil. II, 27 dמן דזרע צַמְחִיןDepois que ele semeou, eles cresceram novamente. Y. Maas. Sh. IV, fim, 55 cצמחיןO trigo no armazém brotará (e será arruinado).</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Mesmo. Targ. O. Ex. X, 5 (Y. mesmo.</p><p><strong>Notas e referências:</strong> Targ. O. Ex. X, 5 (Y. Pe.).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> para fazer crescer, produzir.</p><p><strong>Notas e referências:</strong> Targ. O. Gen. II, 9. Ps. CXXXII, 17 anos.רבתי (חד כות&#x27; 1) דאינון מַצְמְחִין עשבין וכQue eles (os depósitos de trigo) produzirão brotos, e este homem (você) não terá nenhum benefício deles.</p>","gloss_language":"pt-BR"},{"sid":"R00567","lemma":"צֶמַח","gloss":"crescimento, broto, planta.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> crescimento, broto, planta.</p><p><strong>Notas e referências:</strong> Pirké d’R. El. ch. Vלברך צִמְחָהּ של ארץpara abençoar o crescimento da terra. Ib.הארץ מתעברת וצמחה כאשה וכA terra fica grávida, e o que ela produz é como a questão de uma viúva que concebeu em prostituição. Ib.וצמחה … ברכהE o que ela produz é uma semente abençoada. Tanë. Ki Thetsé 4 e as pessoas dizem,זה צ&#x27; רשעEste é um crescimento perverso (o pai de um filho perverso); e.צְמָחִים, צְמָהִיןY. Shek. Eu, imploro. 45 dלא כדי שיהו הצ&#x27; ניכריןNão é necessário esperar com o exame até que os crescimentos sejam suficientemente avançados para serem distinguíveis? B. Kam. 85 aאם עלו בו צ&#x27; מחמת המכה וכSe úlceras crescerem em seu corpo em consequência da ferida, então a ferida está coberta. 48 aהעלתה צ&#x27; se os pulmões têm úlceras (ou bolhas); a. e.</p>","gloss_language":"pt-BR"},{"sid":"R00568","lemma":"צֶמַח","gloss":"Tsema, nome alegórico do futuro Messias.","type":"pr. n.","detailsHtml":"<p><strong>Definição:</strong> Tsema, nome alegórico do futuro Messias.</p><p><strong>Notas e referências:</strong> Y. Ber. II, 5 por topצ&#x27; שמוSeu nome é Ts. Ib.הוא צ&#x27; הוא מנחםO valor numérico das letras.צמחé a mesma das cartas deמנהם(138); Lam. R. para I, 16.</p>","gloss_language":"pt-BR"},{"sid":"R00569","lemma":"צֶמַח","gloss":", כְּפַר צֶ' pr.n. pl. K'far Tsemas, no distrito de Susitha (v.סוּסִיתָא).","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , כְּפַר צֶ&#x27; pr.n. pl. K&#x27;far Tsemas, no distrito de Susitha (v.סוּסִיתָא).</p><p><strong>Notas e referências:</strong> Tosef. Shebi. IV, 10; Y. Dem. II, 22 d superior.</p>","gloss_language":"pt-BR"},{"sid":"R00570","lemma":"צִמְחָא","gloss":"= h. צֶמַח I.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִי&#x27;</p><p><strong>Definição:</strong> = h. צֶמַח I.</p><p><strong>Notas e referências:</strong> Targ. Gen. XIX, 25. Targ. Y. II Deut. XXXII, 2; A. E. — Pl.צְמָחִין, צִמְחֵי, צִיTarg. Y. ib. XXIX, 22. Targ. Ps. LXV, 11, V.נִצְיָיא48 A.חזנהו … צ&#x27; צEle viu os pulmões cobertos de úlceras (ou bolhas). Ab. Zar. 39 aחזא דהוה ביה צ&#x27; ele viu que (o peixe enguia) tinha crescimentos (como escamas).</p>","gloss_language":"pt-BR"},{"sid":"R00571","lemma":"צִמְחוֹן","gloss":"Amigo.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Amigo.</p><p><strong>Notas e referências:</strong> - Pl.צִמְחוֹנִים, צִמְחוֹנִיןMaas. Sh. II, 3תלתן … תאכל צFenugrec dedicado como segundo dízimo pode ser usado como brotos (diretamente das cápsulas, antes que estejam secos); [R.S.: o crescimento de sementes de fenugrec dedicado como segundo dízimo e não redimido, pode ser comido]. Y. ib. 53 c superiorכיני … מותרת להיאכל צO Mishnah quer dizer que pode ser (não deve ser) comido Tosef. ib. II, 1צִמְחוֹנוֹת.</p>","gloss_language":"pt-BR"},{"sid":"R00572","lemma":"צִמְחוֹנָא","gloss":", crescimento, planta.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> , crescimento, planta.</p><p><strong>Notas e referências:</strong> - Pl. Constr.צִמְחוֹנִיTarg. Y. I Deu. XXXII, 2 (V.צִמְחָא).</p>","gloss_language":"pt-BR"},{"sid":"R00573","lemma":"צְמֵי","gloss":"(cmp.צמצםReduzir, cortar, aparar.; mesmo significado.; para causar falta, sofrimento.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (cmp.צמצםReduzir, cortar, aparar.</p><p><strong>Notas e referências:</strong> Targ. Y. Deu. XXI, 12.</p><p><strong>Definição:</strong> mesmo significado.</p><p><strong>Notas e referências:</strong> Y. M. Kat. III, 82 aיתיב מַצְמֵי וכ&#x27; (perh.מִצְמֵיPe.) aparando as unhas.</p><p><strong>Definição:</strong> para causar falta, sofrimento.</p><p><strong>Notas e referências:</strong> Targ. Ps. LXXXI, 8צַמַּיתEd. Lag.ענית; H. textoאענך; v. צוּם).</p>","gloss_language":"pt-BR"},{"sid":"R00574","lemma":"צָמֵיא","gloss":", pl.צְמֵיאִים, v. צָמֵא.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> , pl.צְמֵיאִים, v. צָמֵא.</p>","gloss_language":"pt-BR"},{"sid":"R00575","lemma":"צָמִיד","gloss":"[juntado de perto,]; exatamente a tampa adequada.; unida, unida.; כאדם צ' במלאכתוcomo um homem preso (inseparavelmente ligado) ao seu trabalho.; Um casal.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> צָמַד)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> [juntado de perto,]</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> exatamente a tampa adequada.</p><p><strong>Notas e referências:</strong> צ&#x27; פתיל, v. פָּתִילSnh. 64 a (ref. toהנצמדים, Num. XXV, 5, em contraste comהדבקים, Deu. IV, 4)הנצמדים … כצ&#x27; פ&#x27; que estavam ligados a Baal Peor como uma tampa hermética, enquanto eles estavam ‘apegados ao Senhor’ apenas como duas datas grudadas um ao outro, Yalk. Num. 771.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> unida, unida.</p><p><strong>Notas e referências:</strong> Num. R. s. 20 (ref. toויצמד, Num. XXV,</p><p><strong>Número da acepção:</strong> 3)</p><p><strong>Definição:</strong> כאדם צ&#x27; במלאכתוcomo um homem preso (inseparavelmente ligado) ao seu trabalho.</p><p><strong>Notas e referências:</strong> -3) pulseira, pulseira. Snh. l. c.הנצמדים … כצ&#x27; על ידי אשה וכ&#x27;Que estavam ligados a Baal Peor&#x27;, significa meramente como uma pulseira nas mãos de uma mulher, enquanto &amp;c., v.דָּבַק; a. e. — Pl.צְמִידִים. Num. R. l. c.כצ&#x27; על ידיהcomo &quot;os braceletes em suas mãos&quot; (Gen. XXIV, 22). Ib.זו גזירה קשה … ויצמד בצEsta foi uma calamidade maior do que a do bezerro de ouro, pois ali se diz (Ex. XXXII,</p><p><strong>Definição:</strong> Um casal.</p><p><strong>Notas e referências:</strong> - Pl. como ab. N. R. L. C. (ref. toויצמד, v. supra)בתחלה … צ&#x27; צ&#x27; זוגות וכ&#x27; no início eles foram (para a casa da prostituição) secretamente, mas então eles foram juntos, emparelhados, como falamos deצֶמֶד בָּקָר(um par de bois); Bal. 18.</p>","gloss_language":"pt-BR"},{"sid":"R00576","lemma":"צָמִיד","gloss":"Ver צְמַד.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צְמִידָא</p><p><strong>Notas e referências:</strong> , v. צְמַד- [Yalk. Koh. 989אייתי צמידא, v. סְמִידָא.]</p>","gloss_language":"pt-BR"},{"sid":"R00577","lemma":"צַמְיָיא","gloss":"(צְמֵיNome de um tipo de figos primitivos.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צַ&#x27; קַיְיטָא</p><p><strong>Definição:</strong> (צְמֵיNome de um tipo de figos primitivos.</p><p><strong>Notas e referências:</strong> Y. Maasr. Eu, 49 o topמשיבכר צ&#x27; קQuando a primeira tsamya amadurecer;לא ביכר צ&#x27; ק&#x27; וכ&#x27; se naquele ano o ts. K. não amadureceu cedo.</p>","gloss_language":"pt-BR"},{"sid":"R00578","lemma":"צְמִירְתָּא","gloss":"(צְמַר); Quente;אשתא צFebre inflamatória, V.אֶשָּׁא.; Pedra na bexiga ou rins.","type":"Substantivo feminino","detailsHtml":"<p><strong>Definição:</strong> (צְמַר)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Quente;אשתא צFebre inflamatória, V.אֶשָּׁא.</p><p><strong>Notas e referências:</strong> 25 A. A. Zar. 28 A. e.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Pedra na bexiga ou rins.</p><p><strong>Notas e referências:</strong> B. Mets. 85 a (Ms. R. 1צימרתא; Ag. Hatt.צמדתאGitt.צְמַרְתָּא).</p>","gloss_language":"pt-BR"},{"sid":"R00579","lemma":"צָמִית","gloss":"(צָמַת, v. צְמִיתוּתIrremediavelmente vendido, perdido.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (צָמַת, v. צְמִיתוּתIrremediavelmente vendido, perdido.</p><p><strong>Notas e referências:</strong> Y. Maasr. III, 50 dואין צ&#x27; ביובל(prob. para ser lido:נִצְמָת, v. צָמַתE não se torna irremediável no ano jubileu (Suc. 3b)ואינו נחלט). Arakh. 31 b, v.צְמִיתוּת.</p>","gloss_language":"pt-BR"},{"sid":"R00580","lemma":"*צְמִיתָא","gloss":"(צְמַתReunindo-se, convocando.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (צְמַתReunindo-se, convocando.</p><p><strong>Notas e referências:</strong> Targ. Y. Gen. XXV, 14 (tradução deמשמע, pr.n. pl., cmp.וישמעI Sam. XV, 4); V.צַיְיתָא.</p>","gloss_language":"pt-BR"},{"sid":"R00581","lemma":"צְמִיתוּת","gloss":"Venda irremediável;לצCom certeza, finalmente.","type":"Substantivo feminino","detailsHtml":"<p><strong>Informações do original:</strong> צְמִיתֻת; צָמַת)</p><p><strong>Informações do original:</strong> (b. h.</p><p><strong>Definição:</strong> Venda irremediável;לצCom certeza, finalmente.</p><p><strong>Notas e referências:</strong> Arakh. 31 B (ref. para Lev. XXV, 30)לצ&#x27; לחלוטיןLatsts&#x27;mithuth significa absolutamente;ד&quot;א לצ&#x27; … המתנה מ&quot;ט צמית צOutra interpretação: Latsts &#x27;mithuth é uma amplificação servindo para incluir um dom (para ser final se não redimido dentro de um ano); por quê? Porque...צמיתTeria bastado para indicar uma venda final, e ts&#x27;mithuth amplifica o escopo da lei.</p>","gloss_language":"pt-BR"},{"sid":"R00582","lemma":"צֶמֶל","gloss":"(cmp.צמצם) [ contração, rugas,] o último estágio no crescimento do figo; trnsf. O estágio da puberdade completa da mulher, V.בּוֹחַל.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (cmp.צמצם) [ contração, rugas,] o último estágio no crescimento do figo; trnsf. O estágio da puberdade completa da mulher, V.בּוֹחַל.</p><p><strong>Notas e referências:</strong> Nidd.כמ&quot;ד יצ̇תה מ̇ל̇אהComo se diz, saiu completo. Ib.b.צ&#x27; מלמעלהO sintoma da puberdade completa na parte superior do corpo.</p>","gloss_language":"pt-BR"},{"sid":"R00583","lemma":"צָמַם","gloss":"para serem pressionados juntos, ser contido.; para conter, amarrar.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> para serem pressionados juntos, ser contido.</p><p><strong>Definição:</strong> para conter, amarrar.</p><p><strong>Notas e referências:</strong> Cant. R. para IV, 1 (ref. paraצמתך, ib.)האשה הזאת כשמֵצֶמֶּת שערה וכComo uma mulher amarra seu cabelo atrás, e isso é um ornamento para ela, então o Grande Sinédrio sentou atrás do Templo &amp; C.</p>","gloss_language":"pt-BR"},{"sid":"R00584","lemma":"צמץ","gloss":"Ver מִצְמֵץ.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> Y. Maasr. II, 50 por bot.ומצמץ, v. מִצְמֵץ</p>","gloss_language":"pt-BR"},{"sid":"R00585","lemma":"צִמְצֵם","gloss":"( Pilp.; para contrair; para pressionar, apertar, forçar em confinamento próximo.; Para pressionar, se esconder atrás.; Observar de perto, definir exatamente.; הא אי איפשר לצַMas não é impossível verificar a simultaneidade (de provas de duas testemunhas)? Ib.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> ( Pilp.</p><p><strong>Notas e referências:</strong> deצָמַם)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para contrair; para pressionar, apertar, forçar em confinamento próximo.</p><p><strong>Notas e referências:</strong> Snh. 76 bלרבות את המְצַמְצֵםIsso inclui ele que causou a morte de uma pessoa forçando-o a entrar em um lugar de onde ele não poderia escapar. Ib. 77 aבנזקין … מצמצםem casos de danos a lei não condena quem causa danos através do confinamento (por exemplo, colocando um animal onde foi exposto à insolação). Pesik.מצמצם שכינתו ביניהםforça sua presença divina em seu meio; ib. Vayhi, p. 5 a. Gen. R. s. 5; Lev. R. s. 10צִימְצְמָן בין וכ&#x27; ele os apinhava (os sacerdotes) entre as duas barras da Arca (cmp.צָמַד); A.E.-Passo de parte.מְצוּמְצָם; f. מְצוּמְצֶמֶת; pl.מְצוּמְצָמִין; מְצוּמְצָמוֹתIb. s. 11 (em Chald. dict.)אנא חמיתיה מצ&#x27; ביניהוןEu a vi confinada no meio deles. Prov. 964.ושאר איבריו מצ&#x27; בו וכE o resto de seus membros (do embrião) são pressionados juntos como um nódulo sem forma. III, 50 dמצומתים), v. גּוֹלֶם.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para pressionar, se esconder atrás.</p><p><strong>Notas e referências:</strong> Pesik. SOS, P. 147 B (ref. para Is.ככלה) כיון … היו מְצַמְצְמִין עצמן וכ&quot;Quando os israelitas estavam no Monte Sinai, eles se pressionaram (contra os outros, em reverência) como uma noiva (quando ela se desnuda), abrindo uma (parte de sua roupa) e segurando uma outra parte. Cant. R. para IV, 10 os Dez Mandamentosשהיו מצמצמים עליהן ככלה(sub.עצמןEles se esconderam como uma noiva. Gen. R. s. 45 finalוהיתה … וצִימְצְמָה פניה וכEla se inclinou em sua empregada e apertou seu rosto (contra ela), para que o rei não pudesse vê-la &amp; c; Yalk. ib. 80.הלכה וצמצמה פניה אחורי העמודela foi e apertou o rosto (se escondeu) atrás de uma coluna; e.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> Observar de perto, definir exatamente.</p><p><strong>Notas e referências:</strong> Bekh. II, 6 (17 a)אי אפשר לצַמְצֵם(Mish. Ed.אי אפשרÉ impossível determinar exatamente (que ambas as cabeças saíram simultaneamente). Ib. 17bאפשר לצַ&#x27; בידי שמיםÉ possível verificar a simultaneidade em processos naturais;א&quot;א לצַ&#x27; בידי אדםÉ impossível determinar a simultaneidade nas ações humanas. Shebu. 32 a (ref. toכפרו שניהן כאחתMish. IV,</p><p><strong>Número da acepção:</strong> 4)</p><p><strong>Definição:</strong> הא אי איפשר לצַMas não é impossível verificar a simultaneidade (de provas de duas testemunhas)? Ib.</p><p><strong>Notas e referências:</strong> 28 bחלקו … לפי שא&quot;א לצSe ele dividiu o fogão em duas partes iguais, ambos são impuros, porque é impossível fazer uma divisão exatamente igual.שתהא החמה מְצַמְצֶמֶת בו באחד וכQue o sol deve brilhar sobre ele exatamente no primeiro momento do solstício de Tebeth e do de Tammuz. como ab. Todos. Eu, 57 d bot.חמשׁת … מצExatamente cinco litros. Y. Sabb. II, 5 ao topoשלש על שלש מצExatamente três por três. Gitt. 7 aאם … שמזונותיו מצSe um homem vê que seus meios de apoio estão ficando escassos.צָמַת.</p>","gloss_language":"pt-BR"},{"sid":"R00586","lemma":"צַמְצֵם","gloss":",; Para apertar, confinar.; אמר מְצַמְצְמָא יתי וכNabucodonosor disse, ele (o Senhor, ordenando-me para destruir o Templo) quer me colocar em apuros, para que ele possa fazer comigo como ele fez ib.; para velar a si mesmo.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para apertar, confinar.</p><p><strong>Notas e referências:</strong> Snh. 76 bההוא גברא דמְצַמְצְמָהּ וכ&#x27; (NãoמאSrta. M.דצימצםHebr. Forma) um homem que confinou o animal de seu vizinho para expô-lo à insolação, Yalk. Num. 787דצמצמיה, leia:דצַמְצְמָהּYeb. 46 aארפו ליה וצַמְצְמוּ ליה(ed.וצימצמוEles afrouxaram o cabide em volta do pescoço, e o pressionaram perto do pescoço;צ&#x27; ליה כי היכי וכEles pressionaram, para que ele (quando imerso) não possa antecipá-los e dizer, eu tomo essa imersão como um homem livre para colocar uma pessoa em um dilema. Lam. R. apresenta. (R. Josh.</p><p><strong>Número da acepção:</strong> 2)</p><p><strong>Definição:</strong> אמר מְצַמְצְמָא יתי וכNabucodonosor disse, ele (o Senhor, ordenando-me para destruir o Templo) quer me colocar em apuros, para que ele possa fazer comigo como ele fez ib.</p><p><strong>Notas e referências:</strong> (Zabdi 2)מצמצאAlguns ed. (corr. acc.); ib. a IV, 12.צַמָּה, v. אִיסְטְמָאPara conter o cabelo de voar, para amarrar, véu. Targ. Y. II Gen. XXXVIII, 15 (h. texto)כסתה- [Gen. R. s. 98צמצמתאAlguns Ed., leia:למְצַמְּתָא, v. צְמַת.]</p><p><strong>Definição:</strong> para velar a si mesmo.</p><p><strong>Notas e referências:</strong> Targ. Y. II Gen. XXIV, 65ותתכס).—2) אִצְטַמְטַם(cmp.מזדנזדין, v. זעזע) ser pressionado, quer. Lam. R. para I, 1 (רבתי) אִצְטַמְטְמִינָן לבישרא וכ&#x27; fomos prensados para carne (nossa loja de carne tinha dado para fora). Ib.ואצטמטימתון לחמראE não tínhamos vinho.צְמַת.</p>","gloss_language":"pt-BR"},{"sid":"R00587","lemma":"צַמְצְמָאֵי","gloss":"Ver צִימְצְ'.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צִימְצְ&#x27;</p>","gloss_language":"pt-BR"},{"sid":"R00588","lemma":"צָמַק","gloss":"(b. h.) para encolher.; para causar encolhimento; para secar (ao sol).; para ser reduzido em tamanho (através de fervura & c.).","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) para encolher.</p><p><strong>Notas e referências:</strong> 55 B (Expl.חרותהMish. III, 2)כל שצָמְקָה וכUm animal cujos pulmões encolheram, Tosef. ib. III, 12שצְמוּקָהEd Zuck. (Var.שצמקהSabb. 91 aצמקה וחזרה וכEle encolheu (tornou-se menor do que o tamanho de um figo seco) e então inchou novamente. Y. Orl. I, 61 b topאם צָמְקוּSe as uvas forem encolhidas. Y. Ter. II, 41 d topלִצְמוֹק, v. תֶּפַח. Gen. R. s. 31יִצְמוֹק, v. גָּוַע- Parte, passo.צָמוּק; f. צְמוּקָה, v. supra.</p><p><strong>Definição:</strong> para causar encolhimento; para secar (ao sol).</p><p><strong>Notas e referências:</strong> Y. Maasr. IV, 51 b topפדייו וצִימְּקוֹse ele o redimiu (quando fresco), e deixá-lo secar. Y. Naz. VI, 55 cצימיקו(Leia:צִימֵּיקָן); A.E.-Passo de parte.מְצוּמָּק; f. מְצוּמֶּקֶת; pl.מְצוּמָּקִים; מְצוּמָּקוֹתSabb. 38 aביצים מצOvos cozidos ou torrados em tamanho pequeno.</p><p><strong>Definição:</strong> para ser reduzido em tamanho (através de fervura &amp; c.).</p><p><strong>Notas e referências:</strong> na mesma fonteהמִצְטַמֵּק ורע לוum prato que é deteriorado por ferver para baixo; ib.מִצְטַמְּקוֹת ויפה להןOs ovos são melhorados por &amp;c. Ib. 37 b. Y. ib. III, 5 d. a. fr.</p>","gloss_language":"pt-BR"},{"sid":"R00589","lemma":"צְמַק","gloss":"como precedido. Pi - Parte.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צְמֵיק</p><p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Notas e referências:</strong> Parte, passo.צָמִיק; f. צְמִיקָא&amp;c. Targ. Y. I Num. VI, 3יבשים55 B.הנהו דיכרי דצ&#x27; וכAqueles carneiros cujos pulmões estavam secos.</p><p><strong>Definição:</strong> como precedido. Pi - Parte.</p><p><strong>Notas e referências:</strong> Passo.מְצַמַּקY. Peah VII, 20 bחרוב מצ&#x27; (Nãoכרוב) um prato de alfarrobas secas.</p>","gloss_language":"pt-BR"},{"sid":"R00590","lemma":"צֶמֶק","gloss":"Fruta encolhida, encolhida, figos, datas.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Fruta encolhida, encolhida, figos, datas.</p><p><strong>Notas e referências:</strong> Y. Ter. II, 41 d topo, v.תֶּפַח, a. תָּפַח I.</p>","gloss_language":"pt-BR"},{"sid":"R00591","lemma":"צֶמֶר","gloss":"צמרpara ser pressionado, grosso, quente; cmp.עמרLã, cabelo.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> צמרpara ser pressionado, grosso, quente; cmp.עמרLã, cabelo.</p><p><strong>Notas e referências:</strong> Sabb. 54 a; Shebu. 6 b, v.כָּבַןKil. VII, 2צ&#x27; גפן, v. גֶּפֶןY. ib. II, 27 dגפן הצAlgodão. Tosef. Sabb. IX (X), 3צ&#x27; ארנבים(nãoביים...) cabelos de lebres. Gen. R. s. 37 (ref. toצמרי, Gen. X, 18) (os habitantes de Iamatz são chamados de Zemaritas,)שהן עושין בצPorque eles trabalham com lã. Yeb. 4b.צ&#x27; לפשתים ופשתים לצ&quot;Landen show-fringes para roupas de linho, e linho para roupas de lã; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"R00592","lemma":"צַמָּר","gloss":"Traficante ou trabalhador em lã.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> Traficante ou trabalhador em lã.</p><p><strong>Notas e referências:</strong> - Pl.צַמָּרִים, צַמָּרִיןKel. XXIX, 6חוט … של צ&quot;Os negociadores de lã&quot; (ou tecelões) corda de balanças; B. Bath. 89 a. Erub. X, 9שוק של צ&quot;O mercado dos negociantes de lã&quot;. Eduy. III, 4רשאין הצ&#x27; וכOs tecelões de lã e os tintureiros são autorizados a formar uma parceria para comprar qualquer mercadoria que venha à cidade.מיוצאי צ&#x27;, leia:מִצְרַיִם.]</p>","gloss_language":"pt-BR"},{"sid":"R00593","lemma":"צמר","gloss":"Ver צְמַרְמוֹרַיָּיה.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צ&#x27; מורייה, צ&#x27; מורין</p><p><strong>Notas e referências:</strong> , v. צְמַרְמוֹרַיָּיה</p>","gloss_language":"pt-BR"},{"sid":"R00594","lemma":"צְמַר","gloss":"para ser pressionado, quente.; para aquecer.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> para ser pressionado, quente.</p><p><strong>Definição:</strong> para aquecer.</p><p><strong>Notas e referências:</strong> B. Kam. 60 aדצַמְּרָהּ צַמּוּרֵיEle aumentou o calor das brasas respirando sobre elas.</p>","gloss_language":"pt-BR"},{"sid":"R00595","lemma":"צִמְרָא","gloss":"Ver צִימְרָא.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צִימְרָא</p>","gloss_language":"pt-BR"},{"sid":"R00596","lemma":"צְמָרִי","gloss":"(b. h.) pr.n. Gent.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) pr.n. Gent.</p><p><strong>Notas e referências:</strong> Zemarite. Gen. R. s. 37; Y. Meg. I, 71 b bot., v.חֲמָץ, a. צֶמֶר.</p>","gloss_language":"pt-BR"},{"sid":"R00597","lemma":"צְמַרְמוֹרוֹת","gloss":"(sub.כְּאֵבֵיM.P. (V.צְמַר) rubores febris.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (sub.כְּאֵבֵיM.P. (V.צְמַר) rubores febris.</p><p><strong>Notas e referências:</strong> Nidd. IX, 8 (63 a) (entre os sintomas premonitórios da menstruação)וכמין צ&#x27; אוחזין אותה(Mish. Ed.צְמַרְמוֹרֶתUma espécie de descarga febril a apreende; ib. 63 bצמרמורת(Ar.סְמַרְמוֹרוֹת).</p>","gloss_language":"pt-BR"},{"sid":"R00598","lemma":"צְמַרְמוֹרַיָּיה","gloss":"Arrepios e febre.","type":"Substantivo masculino plural","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צְמַרְמוֹרִין</p><p><strong>Definição:</strong> Arrepios e febre.</p><p><strong>Notas e referências:</strong> Y. Ab. Zar. II, 40 d bot.; Y. Sabb. XIV, 14 d bot.צמר מורין(corr. acc.). Cant. R. para II, 16צמר מורייה(corr. acc.).</p>","gloss_language":"pt-BR"},{"sid":"R00599","lemma":"צְמַרְמוֹרֶת","gloss":"Ver צְמַרְמוֹרוֹת.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צְמַרְמוֹרוֹת</p>","gloss_language":"pt-BR"},{"sid":"R00600","lemma":"צְמַרְמַר","gloss":"Para ser quente.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> Para ser quente.</p><p><strong>Notas e referências:</strong> Targ. Ps. XXXVIII, 11 (h. textoסחרחר; cmp.חַרְחוּרָא).</p>","gloss_language":"pt-BR"},{"sid":"R00601","lemma":"צָמַת","gloss":"(b. h.) [ser pressionados juntos,]; Para encontrar, juntar.; ser esmagado.; para contrair; para reduzir um inchaço por aplicações de vinagre, vinho & c. Pes. 40 aשורן … וחומץ צֹומְתָןEle mergulha os milhos de cevada em vinagre, e isso os liga (preveni a umidade de penetrar e criar fermentação); v.צָפַד.; [para pressionar juntos,]; Para acumular, armazenar, salvar.; Para nos reunirmos, convocar para uma reunião.; para ser anulado.צְמִיתוּת) para ser vendido para sempre, não para ser recuperado no jubileu.","type":"Vocábulo","detailsHtml":"<p><strong>Definição:</strong> (b. h.) [ser pressionados juntos,]</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para encontrar, juntar.</p><p><strong>Notas e referências:</strong> 76 aצוֹמְתִין, v. צוֹמֶת.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> ser esmagado.</p><p><strong>Notas e referências:</strong> B. Kam. 85 bהכהו … וצָמְתָה ידו וכSe alguém golpeasse seu vizinho na mão, e sua mão fosse esmagada, mas se espera que se recupere, Y. Naz. IX, fim, 58 a</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> para contrair; para reduzir um inchaço por aplicações de vinagre, vinho &amp; c. Pes. 40 aשורן … וחומץ צֹומְתָןEle mergulha os milhos de cevada em vinagre, e isso os liga (preveni a umidade de penetrar e criar fermentação); v.צָפַד.</p><p><strong>Notas e referências:</strong> Sabb. 109 a...מי שנגפה צֹומְתָהּ ביין(Ar.בחומץ) aquele cuja mão ou pé foi atingido, pode aplicar vinho (vinegar) para reduzir o inchaço (no sábado).</p><p><strong>Definição:</strong> [para pressionar juntos,]</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Para acumular, armazenar, salvar.</p><p><strong>Notas e referências:</strong> Gen. R. s. 83, fimאבותיך מְצַמְּתִים ואתה מבזבזSeus ancestrais salvaram, e você esbanjou, Yalk. ib. 140מְצַמְצְמִיןYalk. Chr. 1074מצומצמים(lerמצמ&#x27;).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para nos reunirmos, convocar para uma reunião.</p><p><strong>Notas e referências:</strong> Y’lamd. para Gen XLVI, 28 quot. em Ar.צמתך, Cant. IV, 1)שהוא מְצַמְּתָן … בצמאהEle os convoca para as sinagogas, e eles bebem as palavras da Lei com sede. Parte, passo.מְצוּמָּת; pl.מְצוּמָּתִים, מְצוּמָּתִיןa) contido, abstemio, auto-controlado. Cant. R. para VI, 7 (ref. paraצמתך, ib.)על הצנועין ועל המצ&#x27; שבכםdo casto e auto-controlado entre vocês b) convocado para seguir, seguidor. Pesik. Ha&#x27;omer, p. 70 b.צמים, Job V, 5)אברהם וכל המצ&#x27; לוAbraão e todos os seus seguidores, Lev. R. s. 28, Pesik R. s. 18, Yalk. Trabalho 898.</p><p><strong>Definição:</strong> para ser anulado.צְמִיתוּת) para ser vendido para sempre, não para ser recuperado no jubileu.</p><p><strong>Notas e referências:</strong> B. Mets. 79 a (ref. toלצמיתת, Lev. XXV, 30)מי שאין שם יובל נִצְמֶתֶת וכ&quot; aquilo que sem a lei sobre o jubileu seria vendido para sempre, é recuperado pela moeda do jubileu;יצאת זו … אינה נצמתתque exclui um caso como este (uma venda por sessenta anos), onde a venda não seria perpétua mesmo que a lei do jubileu não existisse.</p>","gloss_language":"pt-BR"},{"sid":"R00602","lemma":"צְמַת","gloss":",; contrair, deter, reduzir um inchaço.; Reunir, encontrar.; Para reunir, chamar, convocar para uma reunião.; para sermos reunidos, nos reunir.; Para ser pressionado, quero.","type":"Vocábulo","detailsHtml":"<p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> contrair, deter, reduzir um inchaço.</p><p><strong>Notas e referências:</strong> - Oh, ull. 93 bמִצְמַת צָמְתֵי ליהEles têm o efeito de condensar a superfície da carne (ligando o sangue nas veias). Sot. 20 Bפחדא צָמֵית, v. בִּיעֲתוּתָאSabb. 109 aקא צמית ליה בחלאEstava banhando seu pé em vinagre (no sábado) para reduzir o inchaço; a. e.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Reunir, encontrar.</p><p><strong>Notas e referências:</strong> Y. Dem. Eu, 22 por top.גזר עליהון וצָמְתוּןEle os conjurou (os ratos), e eles se juntaram.</p><p><strong>Definição:</strong> Para reunir, chamar, convocar para uma reunião.</p><p><strong>Notas e referências:</strong> Y. Peah VIII, 21 o topמַצְמֵית וכ&#x27;(ouמְצַמֵּית), v. סְכַןII. Y. Succ. V, implore. 55 aר&#x27; לוי … מיעול מְצַמְּתָא קהלא וכR. L. e R. J. receberam (alternativamente) dois Selas para chamar a congregação para R. J. (ouvir sua palestra); Gen. R. s. 98למצמתא(nãoצמצ&#x27;) Ib. s. 22עד … מצמית לוןEnquanto ele os colecionava (pegar os pães espalhados). Y. Sot. I, bot 17 b.אזל וצַמֵּת ליה וכ&#x27; ele (Absalão) foi e convocou (para acompanhá-lo) dois homens de cada vez, até que ele tinha recolhido duzentos homens, Num. R. s. 9. IV, fim, 66 dומצמית ליה פריטיןe economizou um pouco de dinheiro.</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> para sermos reunidos, nos reunir.</p><p><strong>Notas e referências:</strong> Snh. 109Bיומא דהוו מִצְטַמְּתִין קמת וכAr. (desaparecido em ed.) naquele dia quando os corahitas estavam para se encontrar, ela (a esposa de On) levantou-se e deu-lhe vinho para beber &amp; c.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Para ser pressionado, quero.</p><p><strong>Notas e referências:</strong> Lam. R. para I, 1 (רבתי) אִצְטְמִיתִינָןAr., V.צַמְצֵם.</p>","gloss_language":"pt-BR"},{"sid":"R00603","lemma":"צַן","gloss":"Ver צָנַן, צְנַן..","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צָנַן, צְנַן.</p>","gloss_language":"pt-BR"},{"sid":"R00604","lemma":"צִנָּא","gloss":"Ver צִינָּא.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צְנָא</p><p><strong>Notas e referências:</strong> , v. צִינָּא</p>","gloss_language":"pt-BR"},{"sid":"R00605","lemma":"צַנָּא","gloss":"(v. צִינָּאEu) cesta (de folhas de palma).","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (v. צִינָּאEu) cesta (de folhas de palma).</p><p><strong>Notas e referências:</strong> Taan. 9b.מלא צ&#x27; דתמריUma cesta cheia de datas, Pes.צ&#x27; דאינקוריUma cesta de pássaros, v.אִינְקֹורָאB. Mets. 25 a.בצ&#x27; ופיריQuando encontramos uma cesta ao lado de frutas. Ib.דאית ליה אוגנין לצQuando a cesta tem jantes para manuseá-la.צ&#x27; דמלי סיפריUma cesta cheia de livros, um homem cheio de aprendizado, mas sem método. Ib. 7 a, v.חָרִיף- Pl.צַנַּיָּא, v. צִינָּא I.</p>","gloss_language":"pt-BR"},{"sid":"R00606","lemma":"צִנַּבְרַאי","gloss":"Ver סִנַּבְרַאי.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִנַּבְרַיי</p><p><strong>Notas e referências:</strong> , v. סִנַּבְרַאי</p>","gloss_language":"pt-BR"},{"sid":"R00607","lemma":"צִנָּה","gloss":"v. צָנַן) fivela polida ou cuira (cmp.סַנְוַורְתָּא).","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִינָּה</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> v. צָנַן) fivela polida ou cuira (cmp.סַנְוַורְתָּא).</p><p><strong>Notas e referências:</strong> Midr. Até.מנין … ת&quot;ל וכDe onde aprendemos a incluir o quarto lado (como protegido)? Lemos (Ps. V, 13) &#x27;como com uma cuirass &amp; c&#x27;. Ib. para Ps. XXXV, 2וכי למגן וצ&#x27; וכPreciso de fivelas e cuiras? ib. 722. Naso, ed. Bub. 27 (ref. para Ps. XCI, 4)צ&#x27; אני נעשה לכל מי שהוא סוחר בתורהSou uma cuira para quem viaja com a Lei, Yalk. Ps. 842; Tan. Naso 23.צנן, Josh. XV, 37)צנן שהוא צJerusalém tem o sobrenome de Zenan, porque é uma cuira (o Templo é uma proteção);</p>","gloss_language":"pt-BR"},{"sid":"R00608","lemma":"צִנָּה","gloss":"(v. צָנַן) palma picada, palma de pedra (cuja madeira é muito dura e espinhosa).","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִינָּה</p><p><strong>Definição:</strong> (v. צָנַן) palma picada, palma de pedra (cuja madeira é muito dura e espinhosa).</p><p><strong>Notas e referências:</strong> - Pl.צִנִּים, צִנִּין, צִיY. B. Mets.קורדום … לא צ&#x27; ועצי זיתSe alguém encontrar um machado, ele pode usá-lo para cortar madeira comum, mas não para palmos de pedra e oliveiras; Tosef. ib. II, 22צנםEd Zuck. (Var.צנון, leia:צנהouצנין). Suc. III, 1צִינֵּי … כשרותAs palmas do Monte de Ferro são adequadas (para a coroa festiva), expl. ib. 32 b; Erub. 19 a</p>","gloss_language":"pt-BR"},{"sid":"R00609","lemma":"צִנָּה","gloss":"Frio.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִינָּה</p><p><strong>Informações do original:</strong> צָנַן)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> Frio.</p><p><strong>Notas e referências:</strong> Tosef. Ohol. II, 6נכנסה עליו צ&#x27; ומתEle pegou um resfriado nele e morreu. Y. Sabb. XIV, 14 c bot.תשעים … מתים בצ&#x27; וכ99 homens morrem de frio para um pelas mãos do céu. B. Mets.כל חלי, Deu. VII, 15)זו צIsso significa frio. Tosef. Sabb III (IV), 5צִינָּתָן; Y. ib. III, 6 b topצִינָּתָהּ, v. פּוּגH.; a. fr. — Pl.צִנִּים, צִנִּין, צִיY. B. Kam. VIII, implore.הטיל עליו שלג או צ&#x27; וכSe ele colocar neve ou água gelada, bot.צונןEx. R.S. 25, implore.בקש צ&#x27; … בקש חמים וכ&#x27; (NãoגחליםSe ele quer água gelada, ele consegue. Vayera 10חמין … צונן).—צ&#x27; פחים(adoptado de Prov. XXII, 5) soprando ventos frios, correntes frias; [op.צ&#x27; ופ&#x27; frio e calor, V.פַּחAb. Zar. 3 b; Keth. 30 a; B. Bath. 144 bהכל בידי שמים חוץ מצ&#x27; פTudo está no poder dos céus, exceto a doença das secas frias, como lemos. Prov. 960מצ&#x27; ופ&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"R00610","lemma":"צְנוֹן","gloss":"(v. צָנַןRabanete.","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (v. צָנַןRabanete.</p><p><strong>Notas e referências:</strong> Ber. 36 a; Erub. 28 b, v.פּוּגְלָאBer. 57 B. Ab. Zar. 11 Aצ&#x27; מחתך אוכלRabanetes cortam a comida. Kil.נפוץMakhsh. IV, 6צ&#x27; שבמערהRabanetes que crescem na água de uma caverna.צְנוֹנוֹתSabb. II, 2שמן צÓleo de rabanete. Tosef. ib. II, 3מה יעשו … אלא שמן צ&#x27; בלבדO que farão os alexandrinos que só têm óleo de rabanete? Kil. I, 9; Y. ib. 27 b; a. e.</p>","gloss_language":"pt-BR"},{"sid":"R00611","lemma":"צָנוּעַ","gloss":"aposentado, discreto, casto, decoro.","type":"Substantivo masculino","detailsHtml":"<p><strong>Informações do original:</strong> צָנַע)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> aposentado, discreto, casto, decoro.</p><p><strong>Notas e referências:</strong> Nidd. 12 aכל … נקרא צAquele que cumpre as palavras dos estudiosos é chamado de discreto. Y. Dem. VI, 25 d superiorצְנוּעֵיMish. Ib. 6)שהכשר נקרא צO homem digno é chamado tsanu&#x27;a. Ber. 62 aצ&#x27; בבית הכסאdecente em seus modos no banheiro. Ib.צ&#x27; באורחותיוDecorous em seus caminhos; a. fr. — Pl.צְנוּעִים, צְנוּעִיןCant. R. para VI, 6 (ref. paraרחליםib.)מה רחל זו צנועה כן היו ישראל צ&#x27; וכ&#x27; como o cordeiro é puro, assim como os israelitas eram puros e virtuosos na guerra midianita. Dem. VI, 6צְנוּעֵי בית הלל, v. כָּשֵׁרII. Maas. Sh. V, 1הצ&#x27; מניחין וכA consciência põe dinheiro de lado...צְנוּעָהSabb. 53b.כמה צ&#x27; אשה זוComo essa mulher era casta! Cant. R.L.C., v. supra; a.F. — Pl.צְנוּעוֹתKeth.משום צPelo bem das mulheres virtuosas, Opp.פרוּצותNidd. 12 a, v.עֵד; a. fr.</p>","gloss_language":"pt-BR"},{"sid":"R00612","lemma":"צִנוֹק","gloss":", V. subצִינ'.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִנוֹקָא</p><p><strong>Notas e referências:</strong> , V. subצִינ&#x27;.</p>","gloss_language":"pt-BR"},{"sid":"R00613","lemma":"צִנּוֹר","gloss":"[ qualquer coisa esculpida ou transformada,]; tomada em que a porta-pivô gira, ou pivô.; Tubo de água, bico, ducto.","type":"Substantivo masculino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִינּוֹר</p><p><strong>Informações do original:</strong> צנר, alargamento deצור, cmp.צִינוֹק, טִינָּר, סִינָר &amp;c.)</p><p><strong>Informações do original:</strong> (b. h.;</p><p><strong>Definição:</strong> [ qualquer coisa esculpida ou transformada,]</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> tomada em que a porta-pivô gira, ou pivô.</p><p><strong>Notas e referências:</strong> M. Kat. I, 10 (11 a)הציר והצO pivô e o soquete (ou o soquete e o pivô; v. Rashi em Rabb. D.S.A.L. nota 30).</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> Tubo de água, bico, ducto.</p><p><strong>Notas e referências:</strong> Mikv. IV, 1המניח כלים תחת הצSe colocarmos vasos sob o bico (que alimenta um banho). Ab. Zar. 75 a; Tosef. ib. VIII (IX), 3תחת הצ&#x27; … מקלחיןSob o bico quando suas águas jorram; Y. ib. V, fim, 45 b. Mikv. IV, 3, v.חָטַטTosef. IX (VI), 22 (maior queמזחילה). Ib. 23צ&#x27; המקלח לרשות וכUma sarjeta que corre em direção a uma estrada pública, seja contendo água ou vinho. vagina. Pirké d’R. El. Pl.צִנּוֹרוֹת, צִינּY. Ab. Zar. III, 42 c superior, v.מָשַׁךְTosef. Sabb. VII (VIII), 16; Ber. 50 b, v.מָשַׁךְGen. R. s. 42 (ref. para Gen. XIV,</p><p><strong>Número da acepção:</strong> 3)</p><p><strong>Notas e referências:</strong> [ler:]לא היה שם ים אלא צ&#x27; היאורים וכ&#x27; não havia lago lá na época, mas (depois) os tubos dos dutos (as veias de água nas rochas) estouraram, e um lago foi formado (com ref. a Job XXVIII, 10); Yalk. ib. 72צורות היאור(corr. acc.).</p>","gloss_language":"pt-BR"},{"sid":"R00614","lemma":"צִנּוֹרָא","gloss":",; צ' דדשאSoquete de porta ou pivô.; tubo de água, ducto.; Gancho.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִינּ&#x27;</p><p><strong>Informações do original:</strong> mesmo significado</p><p><strong>Informações do original:</strong> ch.</p><p><strong>Definição:</strong> ,</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> צ&#x27; דדשאSoquete de porta ou pivô.</p><p><strong>Notas e referências:</strong> Ber. 18b.מתותי צ&#x27; דד&#x27; … שקלינהוSra. M. pegue o dinheiro debaixo da porta-pivot em tal e tal lugar; Ed.שקלינהו מתותי בצ&#x27; דד&#x27; וכ&quot;Acredite no que está abaixo do soquete.ומשלים להו אצ&#x27; דד&#x27; e tinha o dinheiro pronto para acertar com eles assim que a porta foi virada. Pes. 94 b.כצ&#x27; דדSe movendo em torno de seu eixo como uma porta em seu soquete.</p><p><strong>Número da acepção:</strong> —2)</p><p><strong>Definição:</strong> tubo de água, ducto.</p><p><strong>Notas e referências:</strong> - Pl. Constr.צִנּוֹרֵי, צִיTarg. Koh. Eu, 7.</p><p><strong>Número da acepção:</strong> —3)</p><p><strong>Definição:</strong> Gancho.</p><p><strong>Notas e referências:</strong> - Pl.צִנּוֹרִין, צִיY. Yeb. XII, 12 d bot. -V.צִנּוֹרָהII.</p>","gloss_language":"pt-BR"},{"sid":"R00615","lemma":"צִנּוֹרָא","gloss":"(v. צִנּוֹר); Salpico de um bico.סִילּוֹןII), Trnsf.צ' (של רוק) ejeção de saliva.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִנּוֹרָה, צִנּוֹרֶת, צִי&#x27;</p><p><strong>Definição:</strong> (v. צִנּוֹר)</p><p><strong>Número da acepção:</strong> 1)</p><p><strong>Definição:</strong> Salpico de um bico.סִילּוֹןII), Trnsf.צ&#x27; (של רוק) ejeção de saliva.</p><p><strong>Notas e referências:</strong> Y. Yoma I, 38 d topנתזה צ&#x27; של רוק וכA saliva de sua boca voou em suas vestes, Tosef. Nidd. V, 3; Nidd. 33 B. Ib.צ&#x27; דעם הארץA saliva de um homem ignorante (não observando a limpeza levítica);משום צ&#x27; וכPorque a saliva de um homem ignorante pode ter caído nela.צִנּוֹרוֹת, צִינּPirké d’R. El.העבים … צִינּוֹרוֹתֵיהֶן וכAs nuvens fazem com que os mares ouçam o som de seus respingos (chuva), e os mares fazem com que as profundezas ouçam &amp;c. (ref. a Ps. XII, 8).</p>","gloss_language":"pt-BR"},{"sid":"R00616","lemma":"צִנּוֹרָא","gloss":"(v. צִנּוֹר) gancho, pino curvo.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִנּוֹרָה, צִי&#x27;</p><p><strong>Definição:</strong> (v. צִנּוֹר) gancho, pino curvo.</p><p><strong>Notas e referências:</strong> Kel. IX, 6 (ed.צְנֵירָה), v. כּוּשׁIb. XIII, 5צ&#x27; שפשטהDehr.צני&#x27;) se um pino curvo foi endireitado. Ib. XI, 9צ&#x27; טהורה(Maim. Ed. Dehr.צניO gancho de um brinco está limpo.צ&#x27; של נזםIb. III, 7ניטל … מפני הצ&#x27; (ed. Zuck.הצינורות) se a parte plana da pá do padeiro é quebrada, é suscetível à impureza por causa do gancho na outra extremidade (usado como um pôquer);ניטלה הצ&#x27; (ed. Zuck.הצינורת) se a extremidade curva é quebrada (v.קַלִּיגְרָפוֹןYoma 12 aמהפך בצ&#x27; ele vira (um pedaço de carne &amp; c. no altar) com o gancho. Tosef. Sabb. VIII (IX), 16כדי לעשות צ&#x27; קטנהcarvão suficiente para forjar um pequeno gancho; ib. IX (X), 5כדי … ממנו צ&#x27; וכ&#x27; suficiente ferro para fazer dele.צ&#x27; וכUm pequeno gancho de bronze. Gen. R. s. 74אפי&#x27; מחט אפי&#x27; צ&#x27; וכVocê não encontrou comigo nem mesmo um alfinete ou um gancho (de seu); Pl.צִנּוֹרוֹת, צִנּוֹרִיּוֹת(fr.צִנּוֹרִיתTosef. Kel. B. Mets. II, 15צ&#x27; התופסות וכOs ganchos que fecham as pedras do moinho de cima. 21 b, sq.מחטין וצ&#x27;Pisos (ou agulhas) e ganchos; a. e.- chald., v.צִנּוֹרָא I.</p>","gloss_language":"pt-BR"},{"sid":"R00617","lemma":"צִנּוֹרִי","gloss":"(precedida.) um pedaço tão grande quanto pode ser pego com um gancho (garfo).","type":"Substantivo masculino","detailsHtml":"<p><strong>Definição:</strong> (precedida.) um pedaço tão grande quanto pode ser pego com um gancho (garfo).</p><p><strong>Notas e referências:</strong> Pesik.כל דאכיל צ&#x27; מן קיסר וכ&quot;Quem come um garfo do que pertence a César, é esfaqueado até a morte (v.סִכָּא); Num. R. s. 8צינורא(corr. acc.).</p>","gloss_language":"pt-BR"},{"sid":"R00618","lemma":"צִנּוֹרִית","gloss":"Ver צִנּוֹרָא III.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צִנּוֹרָאIII</p>","gloss_language":"pt-BR"},{"sid":"R00619","lemma":"צִנּוֹרִיתָא","gloss":"Gancho, uma espécie de garfo para virar as peças no altar.","type":"Substantivo feminino","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִי&#x27;</p><p><strong>Definição:</strong> Gancho, uma espécie de garfo para virar as peças no altar.</p><p><strong>Notas e referências:</strong> - Pl.צִנּוֹרְיָתָא, צִיTarg. O. Ex. XXVII, 3, A.E.מזלג).</p>","gloss_language":"pt-BR"},{"sid":"R00620","lemma":"צִנּוֹרֶת","gloss":"Ver צִנּוֹרָא II.","type":"Vocábulo","detailsHtml":"<p><strong>Notas e referências:</strong> , v. צִנּוֹרָאII, III.</p>","gloss_language":"pt-BR"},{"sid":"R00621","lemma":"צִנְּיָיתָא","gloss":"Ver צִינְּתָא II.","type":"Vocábulo","detailsHtml":"<p><strong>Variantes originais:</strong> Variantes do lema: צִנְּיָתָא</p><p><strong>Notas e referências:</strong> , v. צִינְּתָאII</p>","gloss_language":"pt-BR"}],128);
